        const hRun = mount === "white" ? sprites.horseWhiteRun : sprites.horseRun;
        const hStill = mount === "white" ? sprites.horseWhite : sprites.horse;
        const hImg = p.moving ? hRun[hFrame] : hStill;
        ctx.save();
