      const armSwing = Math.sin((mo.animT || 0) * 1.6) * 2;
      ctx.fillStyle = "rgba(40, 55, 40, 0.85)";
      const armDir = flip ? -1 : 1;
      ctx.fillRect(armDir * 6, -2 + armSwing, armDir * 5, 3);
      ctx.fillRect(armDir * 6, 4 - armSwing, armDir * 5, 3);
